# Stonegate: by stagecoach. Old walls, an arch and a statue nobody can name. Collectors here pay most for the finest of anything.
map STONEGATE set=FARM w=16 h=14 music=SPRING
key # FOREST block
key . GRASS walk
key , GRASS2 walk
key = PATH walk
key r ROCK block
key o BOULDER block
key S STATUE block
key A ARCH block
key w WELL block
key x MINE_CRATE block
key L LAMP block
grid
